contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint extra) public payable {
        require(extra <= 1000000 wei);
        uint amount = 10 wei + extra;
        require(address(this).balance >= amount);

        uint oldPot = c.pot();
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint newPot = c.pot();
            assert(newPot == 0 || newPot == oldPot + 10 wei);
        } else {
            assert(c.pot() == oldPot);
        }
    }

    receive() external payable {}
}

